    conn = get_db()
    row = conn.execute(
        "SELECT id, name, email FROM users WHERE name = ?", (username,)
    ).fetchone()
    conn.close()
    if row is None:
        return jsonify({"error": "not found"}), 404
    return jsonify(dict(row))
EOF
