byj = {}
for f in profs:
    byj.setdefault(f.split('/agent/sessions/')[1], f)
out = {}
for i, c in enumerate(sample['cases']):
    lid = 'L%02d' % (i+1)
    f = byj.get(c['journal'])
    if not f:
        out[lid] = {'relocated': False, 'why': 'journal absent'}; continue
    t, cmds, users = 0, [], []
    for line in open(f, encoding='utf-8', errors='replace'):
        line = line.strip()
        if not line: continue
        try: r = json.loads(line)
        except ValueError: continue
        if not isinstance(r, dict) or r.get('type') != 'message': continue
        m = r.get('message')
        if not isinstance(m, dict): continue
        if m.get('role') == 'user':
            t += 1
            if t == c['turn_index']:
                for x in (m.get('content') or []):
                    if isinstance(x, dict) and x.get('type') == 'text' and x.get('text'):
                        users.append(x['text'])
        if t == c['turn_index'] and m.get('role') == 'assistant':
            for x in (m.get('content') or []):
                if isinstance(x, dict) and x.get('type') == 'toolCall' and isinstance(x.get('arguments'), dict):
                    cmd = x['arguments'].get('command')
                    if isinstance(cmd, str): cmds.append(cmd)
        elif t > c['turn_index']: break
    match = [cmd for cmd in cmds if hashlib.sha256(cmd.encode()).hexdigest() == c['command_sha256']]
    out[lid] = {'relocated': bool(match), 'ncmds': len(cmds),
