const t4 = JSON.parse(readFileSync("/tmp/canny-w70/t4.json","utf8"));
const t6 = JSON.parse(readFileSync("/tmp/canny-w70/t6.json","utf8"));
const rows = readFileSync("/tmp/canny-w70/rows.jsonl","utf8").split("\n").filter(Boolean).map(l=>JSON.parse(l));
const j = new Map(t4.out.map(r=>[r.id,r.noul]));
const h = new Map(t6.out.map(r=>[r.id,r.noul]));
let tp=0,tn=0,fp=0,fn=0,b=0,c=0,both=0,neither=0,missing=0;
const lats=[];
let tin=0,tout=0;
for (const rec of t6.out) { lats.push(rec.ms); tin += rec.input_tokens||0; tout += rec.output_tokens||0; }
for (const row of rows) {
  const jn = j.get(row.id), hn = h.get(row.id);
  if (typeof hn !== "number") { missing++; continue; }
  const jp = jn >= 0.5, hp = hn >= 0.5, y = row.done;
  if (hp && y) tp++; else if (!hp && !y) tn++; else if (hp && !y) fp++; else fn++;
  const jw = jp !== y, hw = hp !== y;
  if (jw && !hw) b++;
  else if (!jw && hw) c++;
  else if (!jw && !hw) both++;
  else neither++;
}
lats.sort((a,b)=>a-b);
const pct = p => lats[Math.min(lats.length-1, Math.ceil(p/100*lats.length)-1)];
function binomP(k, n) {
  // two-sided exact McNemar: P(X<=min(b,c) or X>=max) under Bin(b+c, 0.5)
  const disc = b+c;
  if (!disc) return 1;
  const kmin = Math.min(b,c);
  let p = 0;
  for (let i=0;i<=kmin;i++) p += choose(disc,i);
  for (let i=disc-kmin;i<=disc;i++) if (i>kmin) p += choose(disc,i);
  return p / Math.pow(2, disc);
}
function choose(n,k){ let r=1; for(let i=0;i<k;i++) r = r*(n-i)/(i+1); return r; }
const err = (t6.errors||[]).map(e=>({provider:e.provider, model:e.model, error: String(e.error).replace(/sk-[A-Za-z0-9_-]{8,}/g,"[redacted]").slice(0,240)}));
console.log(JSON.stringify({
  provider: t6.provider, model: t6.model, n: t6.n,
  haiku: {tp,tn,fp,fn, correct: tp+tn, acc: (tp+tn)/rows.length, missing},
  mcnemar: {b, c, both_right: both, both_wrong: neither, p: binomP(Math.min(b,c), b+c)},
  haiku_p50: pct(50), haiku_p95: pct(95), tin, tout,
  failed_route: err,
}, null, 2));
'

